if (FaBLeviaMentorReady($listenerMZ, intval($eventPlayer), $event_mzID)) {
    $owner = intval(FaBIdentityFromMZ($listenerMZ)['player']);
    $mentorUID = intval(FaBIdentityFromMZ($listenerMZ)['object']->UniqueID);
    $attackUID = intval(FaBIdentityFromMZ($event_mzID)['object']->UniqueID);
    if (FaBLeviaMentorLesson($owner, $mentorUID, $attackUID)) {
        FaBMoveUID($mentorUID, 'Banish', $owner);
        $targets = FaBStageSearch($owner, ['specialization'=>true]);
        if ($targets !== '') {
            $chosen = await $owner.MZChoose($targets, "Find_a_specialization_for_arsenal");
            $card = FaBMoveChoice($owner, $chosen, 'Temp', 'Arsenal');
            if ($card !== null) {
                $card->FaceDown = 0;
                FaBRevealChoices($owner, FaBFindUID(intval($card->UniqueID))['mzID']);
            }
        }
        FaBFinishSearch($owner);
    }
}
